@app.get("/", response_class=HTMLResponse)

async def page_dashboard(request: Request):

    ctx = _dashboard_context()

    ctx["active_page"] = "dashboard"

    response = templates.TemplateResponse(request, "dashboard.html", ctx)

    response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"

    return response





@app.get("/search", response_class=HTMLResponse)

async def page_search(request: Request, q: str = Query(default="")):

    response = templates.TemplateResponse(request, "search.html", {

        "active_page": "search",

        "query": q,

        "items": [],

    })

    response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"

    return response





@app.get("/watchlist", response_class=HTMLResponse)

async def page_watchlist(request: Request):

    conn = db.get_conn()

    try:

        rows = db.watchlist_list(conn)

        items = []

        for r in rows:

            item = dict(r)

            snaps = conn.execute(

                "SELECT price_rmb, grade FROM snapshots WHERE item_id=? ORDER BY date DESC LIMIT 1",

                (r["id"],)

            ).fetchone()

            item["latest_price"] = snaps["price_rmb"] if snaps else None

            item["latest_grade"] = snaps["grade"] if snaps else None
            # Read cached trend health
            item_id_str = str(r["id"])
            th_json = db.get_setting(conn, "th_" + item_id_str, "")
            item["trend_health"] = json.loads(th_json) if th_json else None

            item["holding"] = r["holding"] if "holding" in r.keys() else 0

            item["avg_cost"] = r["avg_cost"] if "avg_cost" in r.keys() else 0

            item["quantity"] = r["quantity"] if "quantity" in r.keys() else 0

            items.append(item)



        # Compute holdings summary

        total_buy_cost = db.get_watchlist_holdings_total(conn)

        total_assets_str = db.get_setting(conn, "total_assets", "0")

        try:

            total_assets = float(total_assets_str)

        except (ValueError, TypeError):

            total_assets = 0.0

        position_ratio = (total_buy_cost / total_assets * 100) if total_assets > 0 else 0.0



        response = templates.TemplateResponse(request, "watchlist.html", {

            "active_page": "watchlist",

            "items": items,

            "total_assets": total_assets,

            "total_buy_cost": total_buy_cost,

            "position_ratio": position_ratio,

        })

        response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"

        return response

    finally:

        conn.close()

