@app.post("/api/market/refresh")

async def api_market_refresh(request: Request):

    """Scrape market index + sectors + index K-line for regime detection. Caches to DB."""

    try:
        # csQAQ API: sync HTTP calls, no Playwright needed
        idx = collector.fetch_market_index()
        if idx is None or idx.value == 0:
            idx = collector.MarketIndex(value=0, change_7d=0, mood="neutral")

        index_history = collector.fetch_index_kline()

        # Also fetch sector flow
        sectors = []
        try:
            sectors = collector.fetch_sector_flow()
        except Exception as sec_err:
            print(f"[refresh] sector fetch error: {sec_err}")


        conn = db.get_conn()

        try:

            db.save_market_index(conn, idx.value, idx.change_7d, idx.mood)

            # Bulk save historical K-line data to market_index for analysis
            if index_history and len(index_history) > 1:
                try:
                    conn.executemany(
                        "INSERT OR IGNORE INTO market_index (date, value, change_7d, mood) VALUES (?, ?, 0, '')",
                        [(date_str, val) for date_str, val in index_history]
                    )
                except Exception as ke:
                    print(f"[refresh] kline batch save error: {ke}")

            # Save sectors as JSON in settings

            sectors_data = [{"name": s.name, "change_pct": s.change_pct, "momentum": s.momentum} for s in sectors]

            db.set_setting(conn, "cached_sectors", json.dumps(sectors_data, ensure_ascii=False))
            # Compute and cache index analysis
            analysis = {"has_data": False}
            if index_history and len(index_history) >= 5:
                try:
                    analysis = index_analysis.analyze_index(index_history)
                    db.set_setting(conn, "cached_index_analysis", json.dumps(analysis, ensure_ascii=False))
                except Exception as ae:
                    print(f"[refresh] index analysis error: {ae}")
            conn.commit()

        finally:

            conn.close()



        rr = None

        cfg = {"label": "➖ 数据不足", "position": "--", "strategy": "点击刷新获取最新市场状态"}

        regime_class = ""



        if index_history and len(index_history) >= 5:

            rr = regime.detect_regime(

                index_history=index_history,

                current_value=idx.value,

                change_7d=idx.change_7d,

                mood=idx.mood,

            )

            cfg = regime.regime_strategy(rr)

            regime_class = {

                "trending_up": "regime-bull",

                "trending_down": "regime-bear",

                "ranging": "regime-ranging",

                "volatile": "regime-volatile",

            }.get(rr.regime, "")



        return templates.TemplateResponse(request, "partials/dashboard_refresh.html", {

            "idx": idx,

            "last_update": _now_str(),

            "regime_label": cfg["label"],

            "regime_class": regime_class,

            "regime_position": cfg["position"],

            "regime_strategy": cfg["strategy"],

            "regime_detail": rr,

            "sectors": sectors,

            "analysis": analysis,

        })

    except Exception as e:

        import traceback

        traceback.print_exc()

        return HTMLResponse(
            '<div class="card" style="border-color: rgba(239,68,68,0.5);"><p style="color: var(--red);">刷新失败: ' + str(e) + '</p></div>',

            status_code=200

        )



