@app.get("/api/watchlist/{item_id}/analyze")
async def api_watchlist_analyze(request: Request, item_id: int):
    conn = db.get_conn()
    try:
        row = conn.execute("SELECT * FROM items WHERE id=? AND in_watchlist=1", (item_id,)).fetchone()
        if not row:
            return HTMLResponse(_ae("\u81ea\u9009\u7269\u54c1\u4e0d\u5b58\u5728"))
        name = row["name"]
        rarity = row["rarity"] or "restricted"
        source_val = row["source"] or "case"
        is_disc = bool(row["is_discontinued"])
        disc_years = float(row["discontinued_years"] or 0)
    finally:
        conn.close()

    try:
        from pipeline import collector as _c, item_analysis as _ia, collector_csqaq as _csq

        idx = _c.fetch_market_index()
        if idx is None or idx.value == 0:
            idx = _c.MarketIndex(value=0, change_7d=0, mood="neutral")

        # Use csqaq Playwright collector
        good_id, _ = await _csq.search_good_id(name)
        if not good_id:
            return HTMLResponse(_ae("\u672a\u627e\u5230\u7269\u54c1"))

        item = await _csq.fetch_item_detail(good_id)
        if item is None:
            return HTMLResponse(_ae("\u83b7\u53d6\u7269\u54c1\u8be6\u60c5\u5931\u8d25"))

        # Use 90-day K-line from csqaq
        price_history = [b.close for b in item.kline_90d if b.close > 0]
        volume_history = [b.volume for b in item.kline_90d] if item.kline_90d else None
        supply_history = []

        # Compute market correlation: item price vs index K-line
        sector_corr = 1.0
        try:
            index_kline = _c.fetch_index_kline()
            index_prices = []
            if index_kline and isinstance(index_kline[0], (list, tuple)):
                index_prices = [float(p[1]) for p in index_kline if len(p) >= 2 and float(p[1]) > 0]
            elif index_kline:
                index_prices = [float(p) for p in index_kline if float(p) > 0]
            
            if index_prices and price_history and len(price_history) >= 5:
                import statistics
                min_len = min(len(price_history), len(index_prices))
                if min_len >= 5:
                    p1 = price_history[-min_len:]
                    p2 = index_prices[-min_len:]
                    r1 = [(p1[i]/p1[i-1]-1)*100 for i in range(1, min_len)]
                    r2 = [(p2[i]/p2[i-1]-1)*100 for i in range(1, min_len)]
                    mean1 = statistics.mean(r1); mean2 = statistics.mean(r2)
                    num = sum((a-mean1)*(b-mean2) for a,b in zip(r1,r2))
                    den1 = sum((a-mean1)**2 for a in r1)
                    den2 = sum((b-mean2)**2 for b in r2)
                    if den1 > 0 and den2 > 0:
                        sector_corr = max(-1.0, min(1.0, num / (den1*den2)**0.5))
        except Exception:
            pass

        analysis = _ia.run_item_analysis(
            name=item.name or name,
            prices=price_history,
            volumes=volume_history if volume_history else None,
            supply_hist=supply_history if supply_history else None,
            order_book=item.order_book,
            index_change_7d=idx.change_7d,
        )

        # Render analysis HTML first
        analysis_html = templates.TemplateResponse(request, "partials/analysis.html", {
            "name": analysis.name,
            "price_rmb": analysis.price_rmb,
            "volume_day": analysis.volume_day,
            "volume_total": analysis.volume_total,
            "position": analysis.position,
            "aux": analysis.aux,
            "cycle": analysis.cycle,
            "liquidity": analysis.liquidity,
            "probability": analysis.probability,
            "value": analysis.value,
            "whale": analysis.whale,
            "data_quality": analysis.data_quality,
            "trend_health": analysis.trend_health,
            "fusion_decision": analysis.fusion_decision,
            "valuation_grid": analysis.valuation_grid,
            "error": None,
        })

        # Save report to DB (overwrites previous)
        try:
            from pipeline.watchlist import _generate_item_report_md
            report_md = _generate_item_report_md(analysis)
            conn2 = db.get_conn()
            # Save the rendered HTML body for fast report loading
            html_body = analysis_html.body.decode("utf-8") if hasattr(analysis_html, 'body') else str(analysis_html)
            db.upsert_snapshot(conn2, item_id, price_rmb=analysis.price_rmb,
                              total_score=analysis.value.score, grade=analysis.value.grade,
                              report_md=report_md, report_html=html_body)
            conn2.commit()
            conn2.close()
        except Exception:
            pass

        return analysis_html

    except Exception as e:
        import traceback; traceback.print_exc()
        return HTMLResponse(_ae("\u5206\u6790\u5931\u8d25: " + str(e)[:200]))


