# ============================================================

@app.post("/api/watchlist/scan")
async def api_watchlist_scan(request: Request):
    conn = db.get_conn()
    try:
        items = db.watchlist_list(conn)
        if not items:
            return HTMLResponse('<div class="card"><p>自选列表为空</p></div>')
        total = len(items)
    finally:
        conn.close()

    # Market index from csQAQ HTTP
    idx = collector.fetch_market_index()
    if idx is None or idx.value == 0:
        idx = collector.MarketIndex(value=0, change_7d=0, mood="neutral")

    results = []
    for item_row in items:
        result = {"name": item_row["name"], "status": "ok", "price": 0, "grade": "C", "score": 0, "error": ""}
        try:
            name = item_row["name"]
            rarity = item_row["rarity"] or "restricted"
            source_val = item_row["source"] or "case"
            is_disc = bool(item_row["is_discontinued"])
            disc_years = float(item_row["discontinued_years"] or 0)
            item_id = item_row["id"]

            # csQAQ Playwright: search + detail (K-line included)
            from pipeline import collector_csqaq as _csq
            gid, page_title = await _csq.search_good_id(name)
            if gid == 0:
                result["status"] = "not_found"; result["error"] = "no search results"
                results.append(result); continue

            det = await _csq.fetch_item_detail(gid)
            if det is None:
                result["status"] = "not_found"; result["error"] = "detail fetch failed"
                results.append(result); continue

            # Extract price history from K-line (90-day)
            daily_bars = det.kline_90d if hasattr(det, "kline_90d") and det.kline_90d else []
            prices = [k.close for k in daily_bars if k.close > 0] if daily_bars else []
            volumes = [k.volume for k in daily_bars] if daily_bars else []
            supply_hist = [det.volume_total] * len(prices) if prices else []

            price = det.price_rmb
            vol_day = det.volume_day
            vol_tot = det.volume_total
            if vol_day == 0 and vol_tot > 0:
                vol_day = max(1, vol_tot // 20)

            # Run unified item analysis (includes trend health)
            analysis = item_analysis.run_item_analysis(
                name=det.name or name,
                prices=prices if prices else [price],
                volumes=volumes if volumes else None,
                supply_hist=supply_hist if supply_hist else None,
                order_book=det.order_book,
                index_change_7d=idx.change_7d,
            )

            grade = analysis.value.grade
            score = analysis.value.score
            th = analysis.trend_health or {}

            # Save to DB
            conn2 = db.get_conn()
            try:
                from pipeline.watchlist import _generate_item_report_md
                report_md = _generate_item_report_md(analysis)
                db.save_price(conn2, item_id, price, vol_day, vol_tot)
                db.save_snapshot(conn2, item_id,
                    score_scarcity=0, score_volume=0, score_market=0,
                    total_score=score, grade=grade,
                    recommendation=analysis.value.position_advice,
                    price_rmb=price, report_md=report_md)
                # Cache trend health per item in settings
                import json
                db.set_setting(conn2, f"th_{item_id}", json.dumps(th, ensure_ascii=False))
                conn2.commit()
            finally:
                conn2.close()

            result["price"] = price; result["grade"] = grade; result["score"] = score
            result["th_dir"] = th.get("direction", "flat")
            result["th_score"] = th.get("score", 50)
        except Exception as e:
            result["status"] = "error"; result["error"] = str(e)[:100]
        results.append(result)

    # Build HTML response
    ok_count = sum(1 for r in results if r["status"] == "ok")
    rows = ""
    for r in results:
        si = "\u2705" if r["status"] == "ok" else ("\u26a0\ufe0f" if r["status"] == "not_found" else "\u274c")
        gb = f'<span class="badge badge-{r["grade"].lower()}">{r["grade"]}</span>' if r["status"] == "ok" else '<span class="badge badge-unknown">--</span>'
        ps = f'\u00a5{r["price"]:,.2f}' if r["price"] > 0 else "--"
        th_cell = "<td>--</td>"
        if r["status"] == "ok" and r.get("th_dir"):
            th_e = {"up": "\U0001f4c8", "flat": "\u2796", "down": "\U0001f4c9"}.get(r["th_dir"], "")
            th_cell = f"<td>{th_e} {r.get('th_score', 50)}</td>"
        rows += f"<tr><td>{si}</td><td><strong>{r['name']}</strong></td><td>{ps}</td><td>{gb}</td>{th_cell}<td style='font-size:12px; color: var(--text-muted);'>{r['error']}</td></tr>"

    from datetime import datetime, timezone, timedelta
    now_str = datetime.now(timezone(timedelta(hours=8))).strftime("%Y-%m-%d %H:%M:%S")

    return HTMLResponse(
        f'<div class="card" id="scan-results-card">'
        f'<div class="card-header"><span class="card-title">\U0001f4f3 扫描完成 ({now_str})</span><span class="card-subtitle">{ok_count}/{total} 成功</span></div>'
        f'<div class="table-wrap"><table><thead><tr><th></th><th>物品</th><th>价格</th><th>评级</th><th>趋势健康</th><th>备注</th></tr></thead><tbody>{rows}</tbody></table></div>'
        f'<div style="margin-top: 12px; text-align: right;"><button class="btn btn-outline btn-sm" hx-get="/watchlist" hx-target="body" hx-swap="innerHTML">\U0001f504 刷新页面查看最新数据</button></div>'
        '</div>'
    )


